<canvas id="canvas"></canvas><div class="hud">SERIES <b id="h-wave">SQUARE</b><br>TERMS <b id="h-terms">9</b><br>SPEED <b id="h-speed">1.00</b><br><span class="sub">TRACE</span> <b id="h-trace">0</b></div><?php $interactionHints=[['type'=>'click','label'=>'phase'],['type'=>'drag','label'=>'steer']];require_once __DIR__ . '/includes/interaction-hints.php';?>
<div id="controls" class="drawer-controls"><div><div class="btn-row"><button class="control-btn active" data-wave="square">SQUARE</button><button class="control-btn" data-wave="saw">SAW</button><button class="control-btn" data-wave="pulse">PULSE</button></div></div><div><div class="slider-row"><span class="slider-label">TERMS</span><input type="range" id="sl-terms" min="1" max="29" value="9" step="2"><span class="slider-value" id="sv-terms">9</span></div></div><div><div class="slider-row"><span class="slider-label">SPEED</span><input type="range" id="sl-speed" min="20" max="220" value="100"><span class="slider-value" id="sv-speed">1.00</span></div></div><div><div class="btn-row"><button class="control-btn active" id="btn-spin">SPIN</button><button class="control-btn" id="btn-clear">CLEAR</button></div></div></div><?php require_once __DIR__ . '/includes/drawer-controls.php';?>
<script>(function(){var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,wave='square',terms=9,speed=1,spin=true,t=0,trace=[],phase=0;var hw=document.getElementById('h-wave'),ht=document.getElementById('h-terms'),hs=document.getElementById('h-speed'),hr=document.getElementById('h-trace'),st=document.getElementById('sl-terms'),ss=document.getElementById('sl-speed'),vt=document.getElementById('sv-terms'),vs=document.getElementById('sv-speed');function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px'}function coeff(n){if(wave==='square')return n%2?1/n:0;if(wave==='saw')return (n%2?-1:1)/n;return Math.sin(n*.72)/n}function draw(){if(spin)t+=.018*speed;x.fillStyle='rgba(10,10,15,.18)';x.fillRect(0,0,W,H);x.globalCompositeOperation='lighter';var cx=W*.32,cy=H*.5,px=cx,py=cy;for(var n=1;n<=terms;n++){var a=coeff(n),r=Math.min(W,H)*.18*Math.abs(a),ang=n*(t+phase)+(a<0?Math.PI:0);x.strokeStyle='rgba(0,245,212,.13)';x.lineWidth=1*D;x.beginPath();x.arc(px,py,r,0,Math.PI*2);x.stroke();var nx=px+Math.cos(ang)*r,ny=py+Math.sin(ang)*r;x.strokeStyle=n%2?'rgba(0,245,212,.74)':'rgba(123,44,191,.68)';x.beginPath();x.moveTo(px,py);x.lineTo(nx,ny);x.stroke();px=nx;py=ny}trace.unshift({x:px,y:py});trace=trace.slice(0,Math.floor(W*.55));x.strokeStyle='rgba(123,44,191,.28)';x.beginPath();x.moveTo(px,py);x.lineTo(W*.56,py);x.stroke();x.beginPath();for(var i=0;i<trace.length;i++){var q=trace[i],xx=W*.56+i*D*1.7,yy=q.y;if(i===0)x.moveTo(xx,yy);else x.lineTo(xx,yy)}x.strokeStyle='rgba(0,245,212,.82)';x.lineWidth=2*D;x.stroke();x.fillStyle='rgba(0,245,212,.92)';x.beginPath();x.arc(px,py,4*D,0,Math.PI*2);x.fill();x.globalCompositeOperation='source-over';hr.textContent=trace.length;requestAnimationFrame(draw)}function hud(){hw.textContent=wave.toUpperCase();ht.textContent=terms;vt.textContent=terms;hs.textContent=speed.toFixed(2);vs.textContent=speed.toFixed(2)}c.onclick=e=>{phase+=.4;trace=[];if(typeof SFX!=='undefined')SFX.play('ripple',120)};c.onpointermove=e=>{if(e.buttons){phase+=(e.movementX||0)*.01;if(typeof SFX!=='undefined')SFX.play('move',120)}};document.querySelectorAll('[data-wave]').forEach(b=>b.onclick=()=>{wave=b.dataset.wave;trace=[];document.querySelectorAll('[data-wave]').forEach(q=>q.classList.toggle('active',q===b));hud();if(typeof SFX!=='undefined')SFX.play('toggle')});st.oninput=()=>{terms=+st.value;trace=[];hud()};ss.oninput=()=>{speed=+ss.value/100;hud()};document.getElementById('btn-spin').onclick=e=>{spin=!spin;e.currentTarget.classList.toggle('active',spin);if(typeof SFX!=='undefined')SFX.play('toggle')};document.getElementById('btn-clear').onclick=()=>{trace=[];if(typeof SFX!=='undefined')SFX.play('pop')};addEventListener('resize',resize);resize();hud();draw()})();</script><?php require_once __DIR__ . '/includes/sfx.php';require_once __DIR__ . '/includes/page-end.php';?></body></html>